    result = []
    for i in range(len(arr)):
        if arr[i] % 2 == 0:  # check if number is even
            result.append(arr[i])
        else:
            if i == 0 or i == len(arr) - 1:
                result.append(-1)  # if number is first or last element, replace with -1
            else:
                prev = arr[i - 1]
                next = arr[i + 1]
                if prev % 2 == 0 and next % 2 == 0:
