def find_frequency(string):

    # Initialize an empty dictionary to store the frequencies
    frequency = {}

    # Loop through each character in the string
    for character in string:
        # Check if the character is already in the dictionary
        if character in frequency:
            # If it is, increment the frequency value by 1
            frequency[character] += 1
        else:
            # If it's not, add a new key-value pair to the dictionary
            frequency[character] = 1

    # Return the dictionary of unique characters and their frequencies
    return frequency

