def binary_search(arr, target):

    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2
        mid_element = arr[mid]

        if mid_element == target:
            return mid_element, mid
        elif mid_element < target:
            low = mid + 1
        else:
            high = mid - 1

    return None, None

